import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Read-only narrow lifecycle method/declaration comparison. */
public final class LifecycleMethodDelta {
 static ClassNode read(JarFile j,String name)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(name+".class")).readAllBytes()).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);return c;}
 static byte[] norm(MethodNode m){var c=new ClassNode();c.version=Opcodes.V17;c.access=Opcodes.ACC_PUBLIC;c.name="LifecycleDeltaComparison";c.superName="java/lang/Object";c.methods.add(m);var w=new ClassWriter(0);c.accept(w);return w.toByteArray();}
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[0]);var next=new JarFile(a[1])){var x=read(old,a[2]);var y=read(next,a[2]);if(x.methods.size()!=y.methods.size()||x.fields.size()!=y.fields.size())throw new AssertionError("declaration count");int changed=0,unchanged=0;for(var m:x.methods){var n=y.methods.stream().filter(v->v.name.equals(m.name)&&v.desc.equals(m.desc)).findFirst().orElseThrow();boolean same=Arrays.equals(norm(m),norm(n));if(m.name.equals(a[3])){if(same)throw new AssertionError("missing lifecycle change");changed++;}else{if(!same)throw new AssertionError("unrelated method "+m.name);unchanged++;}}if(changed!=1)throw new AssertionError("one selected method");for(int i=0;i<x.fields.size();i++){var f=x.fields.get(i);var g=y.fields.get(i);if(!Objects.equals(f.name,g.name)||!Objects.equals(f.desc,g.desc)||!Objects.equals(f.value,g.value)||f.access!=g.access)throw new AssertionError("field change");}System.out.println("PASS only "+a[3]+" changed; unchanged methods="+unchanged+"; every field unchanged");}}
}
